select
  cast(null as varchar) as CNPJ_Companhia,
  cast(null as varchar) as Nome_Companhia,
  cast(null as date) as Data_Referencia,
  cast(null as bigint) as ID_Documento,
  cast(null as varchar) as Acionista,
  cast(null as varchar) as Tipo_Pessoa_Acionista,
  cast(null as varchar) as CPF_CNPJ_Acionista,
  cast(null as varchar) as Acionista_Controlador,
  cast(null as varchar) as Participante_Acordo_Acionistas,
  cast(null as double) as Percentual_Acao_Ordinaria_Circulacao,
  cast(null as double) as Percentual_Total_Acoes_Circulacao
where false
